# Build a deterministic reorder list from in-memory stock and minimums.
# A missing stock entry counts as zero units on hand.
func reorder_report(stock, minimums):
    report := []
    for sku in sorted(minimums):
        on_hand := stock[sku] if sku in stock else 0
        needed := minimums[sku] - on_hand
        if needed > 0:
            report = append(report, {"sku": sku, "quantity": needed})
    return report

stock := {"A-100": 4, "B-200": 12}
minimums := {"A-100": 10, "B-200": 8, "C-300": 5}
reorders := reorder_report(stock, minimums)

for row in reorders:
    print(row["sku"], "reorder", row["quantity"])
print("Reorder lines:", len(reorders))

# Calculate an invoice in integer cents to avoid rounding in money totals.
# Return None for invalid quantities, prices, or discounts.
func invoice_total_cents(lines, discount_cents):
    subtotal := 0
    for line in lines:
        if line["quantity"] < 0 or line["unit_cents"] < 0:
            return None
        subtotal += line["quantity"] * line["unit_cents"]
    if discount_cents < 0 or discount_cents > subtotal:
        return None
    return subtotal - discount_cents

lines := [
    {"sku": "NOTEBOOK", "quantity": 3, "unit_cents": 1299},
    {"sku": "PEN", "quantity": 5, "unit_cents": 175},
]
total := invoice_total_cents(lines, 250)
if total is None:
    print("Invalid invoice")
else:
    print("Invoice total (cents):", total)

# Report service availability in basis points (10000 = 100.00%).
# Invalid or empty samples are reported separately from unhealthy services.
func availability_bps(healthy, total):
    if total <= 0 or healthy < 0 or healthy > total:
        return None
    return healthy * 10000 // total

samples := [
    {"service": "api", "healthy": 998, "total": 1000},
    {"service": "worker", "healthy": 970, "total": 1000},
    {"service": "scheduler", "healthy": 0, "total": 0},
]

for sample in samples:
    score := availability_bps(sample["healthy"], sample["total"])
    if score is None:
        print(sample["service"], "no valid sample")
    elif score < 9950:
        print(sample["service"], "alert", score, "bps")
    else:
        print(sample["service"], "healthy", score, "bps")
